const STYLE_ID = 'pointing-bubble-styles'

const CSS = `:where(.pointing-bubble__inner) {
  box-sizing: border-box;
  width: var(--pb-width, max-content);
  max-width: var(--pb-max-width, none);
  padding: var(--pb-padding);
  background: white;
  border: 2px solid gray;
  border-radius: 8px;
}`

export const SHADOW = 'drop-shadow(0 6px 8px rgba(0, 0, 0, 0.25))'

/** Inject default zero-specificity box styles once per document. */
export function injectBubbleStyles(doc: Document = document): void {
  if (doc.getElementById(STYLE_ID)) return
  const style = doc.createElement('style')
  style.id = STYLE_ID
  style.textContent = CSS
  doc.head.prepend(style)
}

import type { BubbleTarget, Point } from './types'

export function isPoint(value: unknown): value is Point {
  return (
    typeof value === 'object' &&
    value !== null &&
    typeof (value as Point).x === 'number' &&
    typeof (value as Point).y === 'number' &&
    !((value as Element).nodeType === 1)
  )
}

/**
 * Resolve a CSS selector or Element. Adapters unwrap framework component
 * instances / refs before calling this.
 */
export function resolveElement(target: BubbleTarget): Element | null {
  if (typeof Element === 'undefined' || target == null) return null
  if (typeof target === 'string') return document.querySelector(target)
  if (target instanceof Element) return target
  return null
}

import type { BoxMeasure, FrameRect } from './types'

export function sameKeys(
  a: Record<string, unknown> | null | undefined,
  b: Record<string, unknown> | null | undefined,
): boolean {
  if (!a || !b) return false
  return Object.keys(a).every((k) => a[k] === b[k])
}

/** Measure root frame including ancestor CSS scale (e.g. Slidev). */
export function measureFrame(root: HTMLElement): FrameRect {
  const rootRect = root.getBoundingClientRect()
  const rootStyle = getComputedStyle(root)
  const width = parseFloat(rootStyle.width) || 0
  const height = parseFloat(rootStyle.height) || 0
  return {
    left: rootRect.left,
    top: rootRect.top,
    width,
    height,
    scaleX: width ? rootRect.width / width : 1,
    scaleY: height ? rootRect.height / height : 1,
    viewportWidth: window.innerWidth,
    viewportHeight: window.innerHeight,
  }
}

export function measureBox(
  boxEl: HTMLElement,
  rootEl: HTMLElement,
  frame: FrameRect,
  manual: boolean,
): BoxMeasure {
  const s = getComputedStyle(boxEl)
  const { scaleX, scaleY } = frame
  const r = boxEl.getBoundingClientRect()
  const rootRect = rootEl.getBoundingClientRect()
  return {
    x: manual ? (r.left - rootRect.left) / scaleX : 0,
    y: manual ? (r.top - rootRect.top) / scaleY : 0,
    width: r.width / scaleX,
    height: r.height / scaleY,
    fill: s.backgroundColor,
    stroke: s.borderTopColor,
    strokeWidth: parseFloat(s.borderTopWidth) || 0,
    radius: s.borderTopLeftRadius,
    zIndex: s.zIndex,
  }
}

import type {
  BoxMeasure,
  FrameRect,
  Geometry,
  LocalRect,
  Placement,
  Point,
  ResolvedPlacement,
  Room,
  TargetAnchor,
} from './types'

export function computeRoom(
  tip: Point,
  frame: FrameRect,
  tailLength: number,
): Room {
  const reach = tip.x - tailLength
  let left = reach
  let right = frame.width ? frame.width - tip.x - tailLength : Infinity
  if (frame.viewportWidth) {
    left = Math.min(left, frame.left / frame.scaleX + reach)
    right = Math.min(
      right,
      (frame.viewportWidth - frame.left) / frame.scaleX - tip.x - tailLength,
    )
  }
  return { left: Math.max(0, left), right: Math.max(0, right) }
}

export function roomierSide(room: Room): 'left' | 'right' {
  return room.left > room.right ? 'left' : 'right'
}

export interface ComputeGeometryOptions {
  tip: Point
  box: BoxMeasure
  frame: FrameRect
  placement: Placement
  targetAnchor: TargetAnchor
  targetRect: LocalRect | null
  room: Room
  tailLength: number
}

export function computeGeometry(opts: ComputeGeometryOptions): Geometry | null {
  const { tip, box: m, frame: f, placement: placementProp, targetRect, room, tailLength: tLen } =
    opts
  if (!m.width || !m.height) return null

  const { width: w, height: h } = m
  const { x: tx, y: ty } = tip
  const manual = placementProp === 'manual'
  const rect = opts.targetAnchor === 'edge' ? targetRect : null

  if (manual) {
    if (rect) {
      const cx = m.x + w / 2
      const cy = m.y + h / 2
      const inside =
        cx >= rect.left &&
        cx <= rect.right &&
        cy >= rect.top &&
        cy <= rect.bottom
      if (!inside) {
        const ex = Math.min(rect.right, Math.max(rect.left, cx))
        const ey = Math.min(rect.bottom, Math.max(rect.top, cy))
        return { placement: 'manual', tx: ex, ty: ey, bx: m.x, by: m.y, w, h }
      }
    }
    return { placement: 'manual', tx, ty, bx: m.x, by: m.y, w, h }
  }

  const tipYFor = (vertical: 'top' | 'bottom') =>
    rect ? (vertical === 'top' ? rect.top : rect.bottom) : ty

  let placement: ResolvedPlacement = placementProp as ResolvedPlacement
  if (placementProp === 'auto') {
    let vertical: 'top' | 'bottom' = ty > (f.height || 600) / 2 ? 'top' : 'bottom'
    let horizontal: 'left' | 'right' = roomierSide(room)

    const { scaleX: sx, scaleY: sy } = f
    if (f.viewportHeight) {
      const fitsAbove = f.top + (tipYFor('top') - h - tLen) * sy >= 0
      const fitsBelow =
        f.top + (tipYFor('bottom') + h + tLen) * sy <= f.viewportHeight
      if (vertical === 'top' && !fitsAbove && fitsBelow) vertical = 'bottom'
      else if (vertical === 'bottom' && !fitsBelow && fitsAbove)
        vertical = 'top'
    }
    if (f.viewportWidth) {
      const fitsLeft = f.left + (tx - w - tLen) * sx >= 0
      const fitsRight =
        f.left + (tx + w + tLen) * sx <= f.viewportWidth
      if (horizontal === 'left' && !fitsLeft && fitsRight) horizontal = 'right'
      else if (horizontal === 'right' && !fitsRight && fitsLeft)
        horizontal = 'left'
    }

    placement = `${vertical}-${horizontal}` as ResolvedPlacement
  }

  const [vertical, horizontal] = (placement as string).split('-') as [
    'top' | 'bottom',
    'left' | 'right',
  ]
  const tipY = tipYFor(vertical)
  return {
    placement,
    tx,
    ty: tipY,
    bx: horizontal === 'left' ? tx - w - tLen : tx + tLen,
    by: vertical === 'top' ? tipY - h - tLen : tipY + tLen,
    w,
    h,
  }
}

import type { Geometry } from './types'

const ANIMATED_KEYS = ['tx', 'ty', 'bx', 'by'] as const
const MANUAL_ANIMATED_KEYS = ['tx', 'ty'] as const

export interface EaseHandle {
  cancel: () => void
}

function prefersReducedMotion(): boolean {
  return (
    typeof matchMedia !== 'undefined' &&
    matchMedia('(prefers-reduced-motion: reduce)').matches
  )
}

/**
 * Ease `from` → `to` with ease-out cubic. Calls `onFrame` each tick.
 * Manual placement only animates tip coords (CSS owns the box).
 */
export function easeGeometry(
  from: Geometry | null,
  to: Geometry | null,
  durationMs: number,
  onFrame: (value: Geometry | null) => void,
): EaseHandle {
  let frame = 0
  const cancel = () => {
    if (typeof cancelAnimationFrame !== 'undefined') cancelAnimationFrame(frame)
  }

  if (
    !to ||
    !from ||
    durationMs <= 0 ||
    typeof requestAnimationFrame === 'undefined' ||
    prefersReducedMotion()
  ) {
    onFrame(to)
    return { cancel }
  }

  const start = performance.now()
  const step = (now: number) => {
    const t = Math.min(1, (now - start) / durationMs)
    const eased = 1 - Math.pow(1 - t, 3)
    const next: Geometry = { ...to }
    const keys =
      to.placement === 'manual' ? MANUAL_ANIMATED_KEYS : ANIMATED_KEYS
    for (const key of keys) {
      next[key] = from[key] + (to[key] - from[key]) * eased
    }
    onFrame(next)
    if (t < 1) frame = requestAnimationFrame(step)
  }
  frame = requestAnimationFrame(step)
  return { cancel }
}

import type { Geometry, TailPaths } from './types'

export interface BuildTailOptions {
  geometry: Geometry
  strokeWidth: number
  radius: string
  tailBaseWidth: number
}

/**
 * Build fill + stroke SVG path `d` for the tail from the box wall facing the tip.
 * Fill extends 1px past the border inner edge to cover zoom snapping seams.
 */
export function buildTailPaths(opts: BuildTailOptions): TailPaths | null {
  const { geometry: c, strokeWidth: bw, radius, tailBaseWidth } = opts
  const { placement, tx, ty, bx, by, w, h } = c
  const r =
    parseFloat(radius) *
      (radius.endsWith('%') ? Math.min(w, h) / 100 : 1) || 0
  const half = tailBaseWidth / 2
  const clamp = (v: number, lo: number, hi: number) =>
    lo > hi ? (lo + hi) / 2 : Math.min(hi, Math.max(lo, v))

  let side: 'left' | 'right' | 'top' | 'bottom' | null = null
  let along = 0
  if (placement === 'manual') {
    const dx = Math.max(bx - tx, tx - (bx + w), 0)
    const dy = Math.max(by - ty, ty - (by + h), 0)
    if (dx > 0 && dx >= dy) {
      side = tx < bx ? 'left' : 'right'
      along = ty
    } else if (dy > 0) {
      side = ty < by ? 'top' : 'bottom'
      along = tx
    } else {
      return null
    }
  } else if (placement !== 'none') {
    const [vertical, horizontal] = placement.split('-') as [
      'top' | 'bottom',
      'left' | 'right',
    ]
    side = horizontal === 'left' ? 'right' : 'left'
    along = by + h * (vertical === 'top' ? 0.65 : 0.35)
  } else {
    return null
  }

  const cover = 1
  const horizontalWall = side === 'top' || side === 'bottom'
  const at = {
    left: (a: number, depth: number): [number, number] => [bx - depth, a],
    right: (a: number, depth: number): [number, number] => [bx + w + depth, a],
    top: (a: number, depth: number): [number, number] => [a, by - depth],
    bottom: (a: number, depth: number): [number, number] => [a, by + h + depth],
  }[side]
  const tipDepth = {
    left: bx - tx,
    right: tx - bx - w,
    top: by - ty,
    bottom: ty - by - h,
  }[side]
  const a = horizontalWall
    ? clamp(along, bx + r + half + bw / 2, bx + w - r - half - bw / 2)
    : clamp(along, by + r + half + bw / 2, by + h - r - half - bw / 2)
  const bend = Math.max(0, Math.min(bw, tipDepth / 2))
  const point = ([x, y]: [number, number]) => `${x} ${y}`
  const edge = (base: number, innerDepth: number) => {
    const ctrl = at(base, bend)
    const dist = Math.hypot(tx - ctrl[0], ty - ctrl[1]) || 1
    const end: [number, number] = [
      ctrl[0] + ((tx - ctrl[0]) * bend) / dist,
      ctrl[1] + ((ty - ctrl[1]) * bend) / dist,
    ]
    return {
      inner: point(at(base, innerDepth)),
      outer: point(at(base, 0)),
      ctrl: point(ctrl),
      end: point(end),
    }
  }
  const tail = (innerDepth: number) => {
    const s1 = edge(a - half, innerDepth)
    const s2 = edge(a + half, innerDepth)
    return (
      `M ${s1.inner} L ${s1.outer} Q ${s1.ctrl} ${s1.end} L ${tx} ${ty} ` +
      `L ${s2.end} Q ${s2.ctrl} ${s2.outer} L ${s2.inner}`
    )
  }
  return {
    fill: `${tail(-bw - cover)} Z`,
    stroke: bw ? tail(-bw) : null,
  }
}

import { easeGeometry, type EaseHandle } from './ease'
import { computeGeometry, computeRoom, roomierSide } from './geometry'
import { measureBox, measureFrame, sameKeys } from './measure'
import { isPoint, resolveElement } from './resolveTarget'
import { injectBubbleStyles, SHADOW } from './styles'
import { buildTailPaths } from './tail'
import type {
  BoxMeasure,
  BubbleConfig,
  BubbleTarget,
  FrameRect,
  Geometry,
  LocalRect,
  Point,
  ResolvedPlacement,
  StyleMap,
  TailPaths,
} from './types'
import { DEFAULT_BUBBLE_CONFIG } from './types'

export interface BubbleRenderState {
  hasTarget: boolean
  placement: ResolvedPlacement
  tip: Point | null
  /** Tip passed to slot/children (resolved geometry tip when available). */
  slotTip: Point | null
  overlayStyle: StyleMap
  boxStyle: StyleMap
  /** When no target, root element is the box. */
  rootIsBox: boolean
  tail: TailPaths | null
  boxFill: string
  boxStroke: string
  boxStrokeWidth: number
  boxZIndex: string
}

export interface BubbleControllerOptions {
  getRootEl: () => HTMLElement | null
  getBoxEl: () => HTMLElement | null
  onChange?: (state: BubbleRenderState) => void
}

export interface BubbleController {
  update: () => void
  setConfig: (partial: Partial<BubbleConfig>) => void
  getConfig: () => BubbleConfig
  getState: () => BubbleRenderState
  destroy: () => void
}

function emptyState(hasTarget: boolean): BubbleRenderState {
  return {
    hasTarget,
    placement: hasTarget ? 'none' : 'none',
    tip: null,
    slotTip: null,
    overlayStyle: {},
    boxStyle: {},
    rootIsBox: !hasTarget,
    tail: null,
    boxFill: '',
    boxStroke: '',
    boxStrokeWidth: 0,
    boxZIndex: 'auto',
  }
}

export function createBubbleController(
  options: BubbleControllerOptions,
): BubbleController {
  injectBubbleStyles()

  let config: BubbleConfig = { ...DEFAULT_BUBBLE_CONFIG }
  let tip: Point | null = null
  let targetRect: LocalRect | null = null
  let box: BoxMeasure | null = null
  let frameRect: FrameRect = {
    left: 0,
    top: 0,
    width: 0,
    height: 0,
    scaleX: 1,
    scaleY: 1,
    viewportWidth: 0,
    viewportHeight: 0,
  }
  let current: Geometry | null = null
  let geometry: Geometry | null = null
  let easeHandle: EaseHandle | null = null
  let resizeObserver: ResizeObserver | null = null
  let state: BubbleRenderState = emptyState(false)

  const emit = () => {
    state = buildState()
    options.onChange?.(state)
  }

  function buildState(): BubbleRenderState {
    const hasTarget = config.target != null
    const manual = config.placement === 'manual'
    const placement: ResolvedPlacement = hasTarget
      ? (current?.placement ?? 'none')
      : 'none'

    const overlayStyle: StyleMap = {
      position: 'absolute',
      inset: '0',
      pointerEvents: 'none',
      filter: config.shadow ? SHADOW : undefined,
    }
    const z = box?.zIndex
    if (z && z !== 'auto') overlayStyle.zIndex = z

    const boxStyle: StyleMap = {
      '--pb-padding':
        typeof config.padding === 'number'
          ? `${config.padding}px`
          : config.padding,
    }
    if (config.maxWidth != null) {
      boxStyle['--pb-max-width'] = `${config.maxWidth}px`
    }

    if (!hasTarget) {
      boxStyle['--pb-width'] = 'fit-content'
      if (config.shadow) boxStyle.filter = SHADOW
    } else {
      Object.assign(boxStyle, {
        position: 'absolute',
        pointerEvents: 'auto',
        visibility: current ? 'visible' : 'hidden',
      })
      if (manual) {
        boxStyle['--pb-width'] = 'fit-content'
      } else {
        Object.assign(boxStyle, {
          left: `${current?.bx ?? 0}px`,
          top: `${current?.by ?? 0}px`,
          margin: '0',
        })
        if (config.maxWidth == null && tip) {
          const room = computeRoom(tip, frameRect, config.tailLength)
          const placed = geometry?.placement ?? config.placement
          const side =
            placed === 'auto'
              ? roomierSide(room)
              : ((placed as string).split('-')[1] as 'left' | 'right')
          boxStyle['--pb-max-width'] = `${room[side]}px`
        }
      }
    }

    const tail =
      hasTarget && current && box
        ? buildTailPaths({
            geometry: current,
            strokeWidth: box.strokeWidth,
            radius: box.radius,
            tailBaseWidth: config.tailBaseWidth,
          })
        : null

    return {
      hasTarget,
      placement,
      tip,
      slotTip: geometry
        ? { x: geometry.tx, y: geometry.ty }
        : tip,
      overlayStyle,
      boxStyle,
      rootIsBox: !hasTarget,
      tail,
      boxFill: box?.fill ?? '',
      boxStroke: box?.stroke ?? '',
      boxStrokeWidth: box?.strokeWidth ?? 0,
      boxZIndex: box?.zIndex ?? 'auto',
    }
  }

  function recomputeGeometry() {
    if (!tip || !box) {
      geometry = null
      startEase(null)
      return
    }
    const room = computeRoom(tip, frameRect, config.tailLength)
    geometry = computeGeometry({
      tip,
      box,
      frame: frameRect,
      placement: config.placement,
      targetAnchor: config.targetAnchor,
      targetRect,
      room,
      tailLength: config.tailLength,
    })
    startEase(geometry)
  }

  function startEase(to: Geometry | null) {
    easeHandle?.cancel()
    easeHandle = easeGeometry(
      current,
      to,
      config.transitionDuration,
      (value) => {
        current = value
        emit()
      },
    )
  }

  function measure() {
    const root = options.getRootEl()
    const boxEl = options.getBoxEl()
    if (!boxEl || config.target == null || !root) return
    const next = measureBox(
      boxEl,
      root,
      frameRect,
      config.placement === 'manual',
    )
    if (
      !sameKeys(
        next as unknown as Record<string, unknown>,
        box as unknown as Record<string, unknown> | null,
      )
    ) {
      box = next
    }
  }

  function update() {
    const root = options.getRootEl()
    if (config.target == null || !root) {
      tip = null
      targetRect = null
      box = null
      geometry = null
      current = null
      emit()
      return
    }

    frameRect = measureFrame(root)
    const el = resolveElement(config.target)
    if (el) {
      const r = el.getBoundingClientRect()
      const { scaleX, scaleY, left, top } = frameRect
      const rect: LocalRect = {
        left: (r.left - left) / scaleX,
        top: (r.top - top) / scaleY,
        right: (r.right - left) / scaleX,
        bottom: (r.bottom - top) / scaleY,
      }
      if (!sameKeys(rect as unknown as Record<string, unknown>, targetRect as unknown as Record<string, unknown> | null)) {
        targetRect = rect
      }
      tip = {
        x: (rect.left + rect.right) / 2,
        y: (rect.top + rect.bottom) / 2,
      }
    } else if (isPoint(config.target)) {
      targetRect = null
      tip = { x: config.target.x, y: config.target.y }
    } else {
      targetRect = null
      tip = null
      box = null
      geometry = null
      current = null
      emit()
      return
    }
    measure()
    recomputeGeometry()
  }

  function onWindowUpdate() {
    update()
  }

  if (typeof window !== 'undefined') {
    window.addEventListener('resize', onWindowUpdate)
    window.addEventListener('scroll', onWindowUpdate, true)
  }

  function ensureObservers() {
    if (typeof ResizeObserver === 'undefined') return
    resizeObserver?.disconnect()
    resizeObserver = new ResizeObserver(() => update())
    const root = options.getRootEl()
    const boxEl = options.getBoxEl()
    if (root) resizeObserver.observe(root)
    if (boxEl) resizeObserver.observe(boxEl)
  }

  // Defer observer attach until first update when els exist
  const originalUpdate = update
  function updateWithObservers() {
    ensureObservers()
    originalUpdate()
  }

  return {
    update: updateWithObservers,
    setConfig(partial) {
      config = { ...config, ...partial }
      updateWithObservers()
    },
    getConfig: () => config,
    getState: () => state,
    destroy() {
      easeHandle?.cancel()
      resizeObserver?.disconnect()
      if (typeof window !== 'undefined') {
        window.removeEventListener('resize', onWindowUpdate)
        window.removeEventListener('scroll', onWindowUpdate, true)
      }
    },
  }
}

export type { BubbleTarget }
